import java.io.*;

public class Main {
    static final int OFF = 1 << 30;      // 2^30, enough to shift [-1e9,1e9] into [0, 2^31)
    static final int MASK = (1 << 31) - 1;

    static final InputStream in = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int bufLen = 0, bufPos = 0;

    static int readByte() throws IOException {
        if (bufPos == bufLen) {
            bufLen = in.read(buf, 0, buf.length);
            bufPos = 0;
            if (bufLen <= 0) return -1;
        }
        return buf[bufPos++];
    }

    static long nextLong() throws IOException {
        int b = readByte();
        while (b != -1 && b != '-' && (b < '0' || b > '9')) b = readByte();
        boolean neg = false;
        if (b == '-') { neg = true; b = readByte(); }
        long res = 0;
        while (b >= '0' && b <= '9') {
            res = res * 10 + (b - '0');
            b = readByte();
        }
        return neg ? -res : res;
    }

    // Counts pairs (earlier, later) in the given order with val_earlier <= val_later (or < if strict),
    // where comparisons use ranks derived from the sorted reference array.
    static long count(long[] vals, long[] ref, boolean strict) {
        int n = vals.length;
        int[] bit = new int[n + 1];
        long total = 0;
        for (int i = 0; i < n; i++) {
            long v = vals[i];
            int lo = 0, hi = n;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (ref[mid] < v) lo = mid + 1; else hi = mid;
            }
            if (strict) {
                for (int j = lo; j > 0; j -= j & (-j)) total += bit[j];
            } else {
                for (int j = lo + 1; j > 0; j -= j & (-j)) total += bit[j];
            }
            for (int j = lo + 1; j <= n; j += j & (-j)) bit[j]++;
        }
        return total;
    }

    public static void main(String[] args) throws IOException {
        int N = (int) nextLong();
        long X1 = nextLong();
        long X2 = nextLong();

        // Pack (a, b) into a single comparable key: order by a, tie-break by b.
        long[] keys = new long[N];
        for (int i = 0; i < N; i++) {
            long a = nextLong() + OFF;
            long b = nextLong() + OFF;
            keys[i] = (a << 31) | b;
        }
        java.util.Arrays.sort(keys);

        // For lines i (smaller a) and j (larger a):
        //   x_int <= X  <=>  a_i*X + b_i <= a_j*X + b_j
        //   x_int <  X  <=>  a_i*X + b_i <  a_j*X + b_j
        long[] c = new long[N]; // evaluation at X2
        long[] d = new long[N]; // evaluation at X1
        for (int t = 0; t < N; t++) {
            long a = (keys[t] >>> 31) - OFF;
            long b = (keys[t] & MASK) - OFF;
            c[t] = a * X2 + b;
            d[t] = a * X1 + b;
        }
        long[] cRef = c.clone();
        long[] dRef = d.clone();
        java.util.Arrays.sort(cRef);
        java.util.Arrays.sort(dRef);

        long ans = count(c, cRef, false) - count(d, dRef, true);
        System.out.println(ans);
    }
}
